// Photo-card images for the Home screen's service grid, keyed by
// ServiceCategory.slug. A slug with no entry here (a category added on the
// backend without a matching image shipped yet) falls back to a plain
// placeholder tile rather than crashing — see HomeScreen.tsx.
//
// Inlined as base64 data URIs rather than require()'d local assets: Metro's
// local-asset pipeline in this monorepo registers each asset with a
// directory-level, non-file-specific "httpServerLocation" (contains
// "unstable_path" — an explicitly experimental Metro feature). Verified
// live on device that this served stale/wrong photo content per file
// (confirmed correct bytes/hash at the HTTP layer, wrong content as
// rendered by the native Image component) — survived Metro cache clears,
// full app uninstalls, fresh Metro ports, and a simulator reboot, so it's
// a Metro/native asset-resolution bug in this setup, not app-level
// caching. Switching to data URIs bypasses that pipeline entirely and
// renders correctly. Source photos live alongside this file as
// cleaning-card.jpg etc. (640x480, top-aligned 4:3 crops keeping the
// worker's face/hands in frame) — if they ever need to change, re-run:
//
//   python3 -c "
//   import base64
//   for slug, name in [('cleaning','cleaning-card'), ('plumbing','plumbing-card'),
//                       ('electrical','electrical-card'), ('gardening','gardening-card')]:
//       with open(f'assets/services/{name}.jpg', 'rb') as f:
//           print(slug, len(base64.b64encode(f.read())), 'chars')
//   "
//
// and regenerate this file's data URIs from the updated source images.

export const SERVICE_IMAGES: Record<string, { uri: string }> = {
  cleaning: { uri: "data:image/jpeg;base64," },
  plumbing: { uri: "data:image/jpeg;base64," },
  electrical: { uri: "data:image/jpeg;base64," },
  gardening: { uri: "data:image/jpeg;base64," },
};
